function sectionBack(item,x){const key=item.key;if(typeof key!=='string'||key==='lang'||!Object.hasOwn(SECTION_CHECKS,key)||SECTION_MODULES[key]&&!window[SECTION_MODULES[key]])return false;try{if(!SECTION_CHECKS[key](item.data))return false}catch{return false}return blankSection(key,x[key])}
