// A change fired by the blur that a mousedown on a button causes must not re-render that button away before its click lands:
// such renders wait until the click has been handled (or the press ends without one).
var renderHeld=false,renderQueued=false,renderHoldTimer=0;
function releaseRender(flush){renderHeld=false;clearTimeout(renderHoldTimer);if(flush&&renderQueued){renderQueued=false;render()}}
function holdRenderForPress(e){const t=e?.target;if(e?.button!==0||!t?.closest?.('#app'))return;if(!(t.closest('button,summary,label,a')||t.matches?.('input[type=checkbox],input[type=radio]'))||t.closest('select,textarea')||t.matches?.('input:not([type=checkbox]):not([type=radio])'))return;renderHeld=true;clearTimeout(renderHoldTimer);renderHoldTimer=setTimeout(()=>releaseRender(true),1500)}
window.addEventListener?.('mousedown',holdRenderForPress,true);window.addEventListener?.('click',()=>{if(renderHeld){renderHeld=false;clearTimeout(renderHoldTimer)}},true);window.addEventListener?.('mouseup',()=>{if(renderHeld)setTimeout(()=>releaseRender(true),0)},true);
/* Keyboard and screen reader users keep their place: after a redraw of the same screen the focus returns to the same control,
   and a new screen starts at its heading. Without this every roll would send the focus back to the top of the page. */
// Modules that keep per-scope drafts are told the current edit scope before every render.
const SCOPED_MODULES=['Lifepath','NetTools','MedicalTools','CriticalInjuryTools','TherapyTools','PharmacyTools','RepairTools','MakerProjects','ReloadTools','DamageApply','DrugTools'];
let lastScreen=null;
const cssText=v=>String(v).replace(/["\\]/g,'\\$&');
function focusMark(){
 try{
  const a=document.activeElement,app=$('#app');if(!a||a===document.body||!app?.contains?.(a))return null;
  let sel=a.tagName.toLowerCase();
  if(a.id)sel+=`[id="${cssText(a.id)}"]`;
  else{const attrs=[...a.attributes].filter(x=>x.name.startsWith('data-')&&x.value.length<=120);if(!attrs.length&&!a.getAttribute('name'))return null;for(const x of attrs)sel+=`[${x.name}="${cssText(x.value)}"]`;if(a.getAttribute('name'))sel+=`[name="${cssText(a.getAttribute('name'))}"]`}
  const index=[...app.querySelectorAll(sel)].indexOf(a);let range=null;try{if(typeof a.selectionStart==='number')range=[a.selectionStart,a.selectionEnd]}catch{}
  return {sel,index:Math.max(0,index),range};
 }catch{return null}
}
function focusAfterRender(mark,screen){
 try{
  const app=$('#app'),changed=lastScreen!==null&&lastScreen!==screen;lastScreen=screen;
  if(changed){const h=app.querySelector?.('.content h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}return}
  if(!mark||(document.activeElement&&document.activeElement!==document.body&&app.contains?.(document.activeElement)))return;
  const el=app.querySelectorAll(mark.sel)[mark.index];if(!el||el.disabled)return;
  el.focus({preventScroll:true});if(mark.range)try{el.setSelectionRange(mark.range[0],mark.range[1])}catch{}
 }catch{}
}
function render(){if(renderHeld){renderQueued=true;return}renderQueued=false;for(const name of SCOPED_MODULES)window[name]?.setScope(syncAdapter?.getScope()||null);if(state.view==='sheet')window.EquipmentTools?.setScope(syncAdapter?.getScope()||null);let content;try{content=state.view==='room'?(window.Room?.render?.()||''):state.view==='overview'?overview():state.view==='characters'?characters():state.view==='rules'?rules():state.view==='dice'?dice():state.view==='catalog'?catalog():state.view==='campaigns'?(window.CampaignIO?.decorate||String)(window.Campaigns.render(state.campaigns,state.characters,state.lang,state.gmWorkspace),state):state.view==='book'?window.Book.render(state.lang,{lang:state.lang,data:state.bookBookmarks,scope:editScope(),page:window.Book.getPage()}):state.view==='net'?(syncAdapter?.getScope()?window.NetTools.render({lang:state.lang,architectures:state.netArchitectures,characters:state.characters}):'<div class="card">'+(state.lang==='ru'?'Подождите, данные ещё загружаются.':'Please wait, data is still loading.')+'</div>'):state.view==='gm'?(syncAdapter?.getScope()?window.GMTools.render({lang:state.lang,workspace:state.gmWorkspace,campaigns:state.campaigns})+(window.NightMarket?.render(state.lang)||'')+(window.GMExtras?.render(state.lang)||''):'<div class="card">'+(state.lang==='ru'?'Подождите, данные ещё загружаются.':'Please wait, data is still loading.')+'</div>'):state.view==='medical'?(syncAdapter?.getScope()?window.MedicalTools.render({lang:state.lang,characters:state.characters})+(window.CriticalInjuryTools?.render({lang:state.lang,characters:state.characters,view:'medical'})||'')+(window.TherapyTools?.render({lang:state.lang,characters:state.characters})||'')+(window.PharmacyTools?.render({lang:state.lang,characters:state.characters})||'')+(window.CyberSurgery?.render(state.lang,state.characters,appScopeEpoch)||''):'<div class="card">'+(state.lang==='ru'?'Подождите, данные ещё загружаются.':'Please wait, data is still loading.')+'</div>'):state.view==='repair'?(syncAdapter?.getScope()?window.RepairTools.render({lang:state.lang,characters:state.characters}):'<div class="card">'+(state.lang==='ru'?'Подождите, данные ещё загружаются.':'Please wait, data is still loading.')+'</div>')+(window.CraftingTools?.render(state.lang)||'')+(syncAdapter?.getScope()?(window.MakerProjects?.render({lang:state.lang,characters:state.characters})||''):''):state.view==='combat'?combatView():state.view==='builder-choice'?builderChoice():state.view==='builder'?window.Builder.render(builderContext()):state.view==='quick-builder'?window.QuickBuilder.render(quickBuilderContext()):state.view==='lifepath'?window.Lifepath.render(state.lang,state.characters):sheet(active())}catch(error){globalThis.console?.error?.(error);content='<div class="card" role="alert">'+(state.lang==='ru'?'Не удалось показать этот раздел. Обновите страницу — остальные разделы работают.':'This section could not be shown. Reload the page — the other sections still work.')+'</div>'}const focusWas=focusMark(),screen=state.view+'|'+(state.view==='sheet'?state.active:'');$('#app').innerHTML=appShell(content);window.ShellUI?.sync();focusAfterRender(focusWas,screen);if(state.view==='sheet')window.SkillFilter?.apply(document.querySelector('.skills-list')?.closest('.card'),state.lang);if(state.view==='sheet')window.InventoryFilter?.apply(document.querySelector('#sheet-items'),state.lang);if(state.view==='sheet')window.SheetNavigation?.refresh(document.querySelector('.sheet-jump-nav'),state.lang);;document.documentElement.lang=state.lang;document.title='Night City // RED — '+tr('appLabel')}
// Persistent one-use-per-round tracking for an explicitly confirmed Spot Weakness hit.
function spotUsage(c){const v=c?.extra?.soloSpotUsage;if(v===undefined)return {version:1,uses:[]};if(!v||typeof v!=='object'||Array.isArray(v)||v.version!==1||!Array.isArray(v.uses)||v.uses.length>5000)return null;const ids=new Set(),rounds=new Set(),norm=x=>x.trim().normalize('NFKC').toLocaleLowerCase();for(const u of v.uses){if(!u||typeof u!=='object'||Array.isArray(u)||typeof u.id!=='string'||!u.id||u.id.length>160||ids.has(u.id)||typeof u.battle!=='string'||!u.battle.trim()||u.battle.length>100||!Number.isSafeInteger(u.round)||u.round<1||u.round>9999||!Number.isSafeInteger(u.bonus)||u.bonus<1||u.bonus>10||!Number.isSafeInteger(u.weaponBonus)||u.weaponBonus< -99||u.weaponBonus>99||typeof u.weapon!=='string'||u.weapon.length>100||!Array.isArray(u.dice)||u.dice.length<1||u.dice.length>30||u.dice.some(x=>!Number.isSafeInteger(x)||x<1||x>6)||!Number.isSafeInteger(u.total)||u.total!==u.dice.reduce((n,x)=>n+x,0)+u.weaponBonus+u.bonus)return null;const key=JSON.stringify([norm(u.battle),u.round]);if(rounds.has(key))return null;ids.add(u.id);rounds.add(key)}return v}
function pushRoll(label,detail,total,faces=null,meta=null){state.history.unshift({label,detail,total});state.history=state.history.slice(0,20);pendingRoll={label,detail,total,faces:Array.isArray(faces)?faces:null,at:Date.now()};save();window.Room?.roll?.({label,detail,total,character:state.view==='sheet'?active()?.name||'':'',...(meta?.initiative&&state.view==='sheet'&&active()?{initiative:true,characterId:active().id}:{})})}
function checkRoll(stat,skill,mod,label,options={}){const first=d(10),recovered=first===1&&options.ignoreFumble===true,extra=(first===1&&!recovered)||first===10?d(10):0,total=first+(first===1?-extra:extra)+stat+skill+mod,dv=Number.isSafeInteger(options.dv)&&options.dv>0&&options.dv<=99?options.dv:0,beat=dv?total>dv:null;let crit=first===10?tr('criticalSuccess'):first===1&&!recovered?tr('criticalFailure'):'';pushRoll(label||tr('rollCheck'),`1d10 ${first}${extra?` ${first===1?'−':'+'} ${extra} (${crit})`:''}${recovered?' (Fumble Recovery)':''} + ${stat} + ${skill} ${mod?`${mod>0?'+':'−'} ${Math.abs(mod)}`:''}${dv?` = ${total} ${beat?'>':'≤'} DV ${dv} — ${beat?(state.lang==='ru'?'успех':'success'):(state.lang==='ru'?'провал':'failure')}`:''}`,total,[{v:first,s:10,k:first===10?'crit':first===1&&!recovered?'fumble':''},...(extra?[{v:extra,s:10,k:'extra'}]:[])]);return {total,crit,first,extra,dv,beat}}
